-- Append-only core runtime. Stored 0001 rows remain valid.
CREATE TABLE core_write_guards (id TEXT PRIMARY KEY NOT NULL, accepted INTEGER NOT NULL CHECK (accepted = 1));
CREATE TRIGGER core_write_guard_cleanup AFTER INSERT ON core_write_guards BEGIN DELETE FROM core_write_guards WHERE id=NEW.id; END;
CREATE TABLE workspace_policies (workspace_id TEXT PRIMARY KEY NOT NULL REFERENCES workspaces(id), profile_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE magic_links (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL, token_digest TEXT UNIQUE NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE identity_states (id TEXT PRIMARY KEY NOT NULL, state_digest TEXT UNIQUE NOT NULL, nonce TEXT NOT NULL, verifier TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE request_limits (key TEXT PRIMARY KEY NOT NULL, count INTEGER NOT NULL, expires_at TEXT NOT NULL);

CREATE TABLE core_acl_epoch (id INTEGER PRIMARY KEY CHECK(id=1), epoch INTEGER NOT NULL);
INSERT INTO core_acl_epoch VALUES (1,0);
CREATE TRIGGER core_acl_page_grants_insert AFTER INSERT ON page_grants BEGIN UPDATE core_acl_epoch SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER core_acl_page_grants_update AFTER UPDATE ON page_grants BEGIN UPDATE core_acl_epoch SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER core_acl_page_grants_delete AFTER DELETE ON page_grants BEGIN UPDATE core_acl_epoch SET epoch=epoch+1 WHERE id=1; END;
