CREATE TRIGGER core_acl_pages_update AFTER UPDATE OF container_id,parent_page_id,lifecycle,access_inheritance,deleted_at,trashed_at ON pages BEGIN UPDATE core_acl_epoch SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER core_acl_containers_update AFTER UPDATE OF visibility,guest_access,public_link_access,anonymous_access,archived_at,trashed_at ON containers BEGIN UPDATE core_acl_epoch SET epoch=epoch+1 WHERE id=1; END;
CREATE TABLE core_entity_revisions (id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL REFERENCES workspaces(id),entity_kind TEXT NOT NULL,entity_id TEXT NOT NULL,content_hash TEXT NOT NULL,content_json TEXT NOT NULL,author_member_id TEXT REFERENCES members(id),created_at TEXT NOT NULL);
CREATE INDEX core_entity_revisions_entity ON core_entity_revisions(entity_kind,entity_id,created_at,id);
CREATE TABLE core_job_failures (id TEXT PRIMARY KEY NOT NULL,kind TEXT NOT NULL,attempts INTEGER NOT NULL,state TEXT NOT NULL,error_code TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE core_event_cursors (consumer TEXT PRIMARY KEY NOT NULL,sequence INTEGER NOT NULL);
